using System.Security.Cryptography;
using System.Text;
using Npgsql;
namespace Bck.Api.Features.Auth;
public sealed record CreatePairingRequest(string DeviceMode);public sealed record CreatePairingResponse(string PairingCode,DateTimeOffset ExpiresAt);public sealed record ConsumePairingRequest(string PairingCode,Guid DeviceId,string DeviceName,string Platform,string Username,string Password);public sealed record ConsumePairingResponse(Guid GroupId,Guid DeviceId,Guid UserId,string DeviceMode);
public sealed class DevicePairingService(IConfiguration configuration){private static readonly TimeSpan Lifetime=TimeSpan.FromMinutes(10);public async Task<CreatePairingResponse>CreateAsync(Guid g,Guid u,string mode,CancellationToken ct){mode=mode.Trim().ToUpperInvariant();if(mode is not("PERSONAL" or "SHARED"))throw new ArgumentException("Modo do dispositivo inválido.");var raw=Code();var now=DateTimeOffset.UtcNow;await using var c=new NpgsqlConnection(Cs());await c.OpenAsync(ct);await using var q=new NpgsqlCommand("INSERT INTO device_pairing_token(group_id,created_by_user_id,token_hash,requested_device_mode,expires_at) VALUES($1,$2,$3,$4,$5)",c);q.Parameters.AddWithValue(g);q.Parameters.AddWithValue(u);q.Parameters.AddWithValue(Hash(raw));q.Parameters.AddWithValue(mode);q.Parameters.AddWithValue(now.Add(Lifetime));await q.ExecuteNonQueryAsync(ct);return new(raw,now.Add(Lifetime));}public async Task<ConsumePairingResponse?>ConsumeAsync(ConsumePairingRequest r,CancellationToken ct){if(string.IsNullOrWhiteSpace(r.PairingCode)||r.DeviceId==Guid.Empty||string.IsNullOrWhiteSpace(r.DeviceName)||string.IsNullOrWhiteSpace(r.Platform)||string.IsNullOrWhiteSpace(r.Username)||string.IsNullOrEmpty(r.Password))return null;await using var c=new NpgsqlConnection(Cs());await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);Guid tid,g;string mode;await using(var q=new NpgsqlCommand("SELECT id,group_id,requested_device_mode FROM device_pairing_token WHERE token_hash=$1 AND consumed_at IS NULL AND expires_at>now() FOR UPDATE",c,tx)){q.Parameters.AddWithValue(Hash(r.PairingCode.Trim().ToUpperInvariant()));await using var rd=await q.ExecuteReaderAsync(ct);if(!await rd.ReadAsync(ct)){await tx.RollbackAsync(ct);return null;}tid=rd.GetGuid(0);g=rd.GetGuid(1);mode=rd.GetString(2);}Guid uid;string ph;await using(var q=new NpgsqlCommand("SELECT id,password_hash FROM bck_user WHERE group_id=$1 AND lower(username)=lower($2) AND active=true LIMIT 1",c,tx)){q.Parameters.AddWithValue(g);q.Parameters.AddWithValue(r.Username.Trim());await using var rd=await q.ExecuteReaderAsync(ct);if(!await rd.ReadAsync(ct)){await tx.RollbackAsync(ct);return null;}uid=rd.GetGuid(0);ph=rd.GetString(1);}if(!PasswordHasher.Verify(r.Password,ph)){await tx.RollbackAsync(ct);return null;}await using(var q=new NpgsqlCommand("INSERT INTO device(id,group_id,name,platform,device_mode,status,is_principal) VALUES($1,$2,$3,$4,$5,'ACTIVE',false) ON CONFLICT(id) DO NOTHING",c,tx)){q.Parameters.AddWithValue(r.DeviceId);q.Parameters.AddWithValue(g);q.Parameters.AddWithValue(r.DeviceName.Trim());q.Parameters.AddWithValue(r.Platform.Trim().ToUpperInvariant());q.Parameters.AddWithValue(mode);if(await q.ExecuteNonQueryAsync(ct)!=1){await tx.RollbackAsync(ct);return null;}}await using(var q=new NpgsqlCommand("INSERT INTO device_user(device_id,user_id) VALUES($1,$2)",c,tx)){q.Parameters.AddWithValue(r.DeviceId);q.Parameters.AddWithValue(uid);await q.ExecuteNonQueryAsync(ct);}await using(var q=new NpgsqlCommand("UPDATE device_pairing_token SET consumed_at=now() WHERE id=$1 AND consumed_at IS NULL",c,tx)){q.Parameters.AddWithValue(tid);if(await q.ExecuteNonQueryAsync(ct)!=1){await tx.RollbackAsync(ct);return null;}}await tx.CommitAsync(ct);return new(g,r.DeviceId,uid,mode);}private string Cs()=>configuration.GetConnectionString("Postgres")??Environment.GetEnvironmentVariable("BCK_POSTGRES_CONNECTION")??throw new InvalidOperationException("PostgreSQL connection is not configured.");private static string Code(){const string chars="ABCDEFGHJKLMNPQRSTUVWXYZ23456789";var bytes=RandomNumberGenerator.GetBytes(8);var b=new StringBuilder(9);for(var i=0;i<8;i++){if(i==4)b.Append('-');b.Append(chars[bytes[i]%chars.Length]);}return b.ToString();}private static string Hash(string t)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(t)));}
